# snake_to_camel :: 'hello_world'
def snake_to_camel(s):
    parts = s.split('_')
    return parts[0] + ''.join(p.capitalize() for p in parts[1:])

if __name__ == '__main__':
    print(snake_to_camel('hello_world'))

